<?php require_once __DIR__.'/includes/auth.php'; require __DIR__.'/config/database.php';
$q=is_string($_GET['q']??null)?trim($_GET['q']):''; $category=filter_var($_GET['category']??null,FILTER_VALIDATE_INT);
$sql='SELECT p.*,c.name AS category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE 1=1'; $args=[];
if($q!=='') {$sql.=' AND (p.name LIKE ? OR p.description LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}
if($category){$sql.=' AND category_id=?';$args[]=$category;}
$s=$pdo->prepare($sql.' ORDER BY p.id DESC');$s->execute($args);$products=$s->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shop | EcoCommerce</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php include __DIR__.'/includes/navbar.php'; ?><section class="products-section"><h1>Find your next favorite</h1><p>Everyday essentials. Thoughtful prices.</p><form method="get" class="catalog-filter"><input name="q" placeholder="Search products" value="<?= e($q) ?>"><select name="category"><option value="">All categories</option><?php foreach($pdo->query('SELECT * FROM categories ORDER BY name') as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $category==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select><button class="product-btn">Search</button></form><div class="product-grid"><?php foreach($products as $product): ?><article class="product-card"><div class="product-image">📦</div><small><?= e($product['category_name']??'Essentials') ?></small><h3><?= e($product['name']) ?></h3><p><?= e($product['description']) ?></p><p class="price">৳<?= number_format($product['price'],2) ?></p><p><?= (int)$product['stock'] ?> available</p><a class="product-btn" href="product.php?id=<?= (int)$product['id'] ?>">View product</a></article><?php endforeach ?></div><?php if(!$products): ?><p>No products match your search. Try another category or keyword.</p><?php endif ?></section></body></html>